const body = $json.body || $json;

const orderId = String(body.order_id || body.id || 'SIN-ID');
const customerName = body.customer_name || 'Cliente desconocido';
const customerEmail = body.customer_email || body.email || '';
const platform = body.platform || 'Web';
const shippingAddress = body.shipping_address || '';
const paymentStatus = body.payment_status || 'pending';
const total = body.total || 0;
const items = body.items || [];

if (!items || items.length === 0) {
  throw new Error('Pedido sin articulos');
}

const skus = items.map(i => i.sku).filter(s => s);
const itemsSummary = items.map(i => i.title + ' (' + i.sku + ') - ' + i.price + ' eur').join('; ');

return [{
  orderId: orderId,
  customerName: customerName,
  customerEmail: customerEmail,
  platform: platform,
  shippingAddress: shippingAddress,
  paymentStatus: paymentStatus,
  total: total,
  items: items,
  skus: skus,
  itemsSummary: itemsSummary,
  fecha: new Date().toISOString().split('T')[0]
}];

const orderData = $('Procesar Pedido').first().json;
const bookResults = $json.results || $json.data || [];
const currentItem = $('Iterar Items').first().json;

let result = {
  sku: currentItem.sku,
  title: currentItem.title,
  status: 'no_encontrado',
  action: 'incidencia',
  pageId: null,
  estadoActual: ''
};

if (bookResults.length > 0) {
  const book = bookResults[0];
  const props = book.properties || {};
  const estado = props['Estado publicacion'] ? (props['Estado publicacion'].select?.name || '') : '';

  result.pageId = book.id;
  result.estadoActual = estado;

  if (estado === 'Publicado') {
    result.status = 'disponible';
    result.action = 'reservar';
  } else {
    result.status = 'no_disponible';
    result.action = 'incidencia';
  }
}

return [{
  ...orderData,
  ...result
}];

return [{
  json: {
    reserved: true,
    sku: $json.sku,
    pageId: $json.pageId
  }
}];

return [{
  json: {
    reserved: false,
    sku: $json.sku,
    reason: $json.status
  }
}];

const orderData = $('Procesar Pedido').first().json;

// Recopilar todos los resultados del loop
const allItems = $('Tras Reservar').all().map(r => r.json);
const allIncidences = $('Tras Incidencia').all().map(r => r.json);

const reservedBooks = allItems.filter(r => r.reserved);
const failedBooks = allIncidences.filter(r => !r.reserved);
const hasIncidence = failedBooks.length > 0;

const incidenceDetails = failedBooks.map(f => 'SKU ' + f.sku + ': ' + f.reason);

return [{
  orderId: orderData.orderId,
  customerName: orderData.customerName,
  customerEmail: orderData.customerEmail,
  platform: orderData.platform,
  shippingAddress: orderData.shippingAddress,
  total: orderData.total,
  itemsSummary: orderData.itemsSummary,
  fecha: orderData.fecha,
  hasIncidence: hasIncidence,
  incidenceDetails: incidenceDetails,
  reservedCount: reservedBooks.length,
  failedCount: failedBooks.length,
  orderStatus: hasIncidence ? 'Incidencia' : 'Pagado'
}];

